event Unpaused();

event Approval(
address indexed owner,
address indexed spender,
uint256 value
);

event AddedToBlacklist(address indexed account);
event RemovedFromBlacklist(address indexed account);

mapping(address => mapping(address => uint256)) private _allowances;
